-- category mostly-additional + common phrase, count
-- cost variable: products in the subtree = 6689 (scales with products)
SELECT count(*) FROM (SELECT 1 FROM catalog_product p WHERE p.primary_category_id = ANY('{c57c017b-d6f7-5990-82bf-635533003629}'::uuid[]) AND p.name ILIKE '%pro%' UNION ALL SELECT 1 FROM (SELECT DISTINCT p.id FROM catalog_product_category pc JOIN catalog_product p ON p.id = pc.product_id WHERE pc.category_id = ANY('{c57c017b-d6f7-5990-82bf-635533003629}'::uuid[]) AND NOT (p.primary_category_id = ANY('{c57c017b-d6f7-5990-82bf-635533003629}'::uuid[])) AND p.name ILIKE '%pro%') a LIMIT 10001) bounded;
